import { Group, Mesh, PlaneGeometry, Color, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, texture, Fn, fract, sin, time, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.name = 'hub-collection-card-1-label';

  const THREE = ctx.THREE;
  const specColors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = new Color(specColors.ink ?? '#16161d');
  const paper = new Color(specColors.paper ?? '#e8ecf2');
  const accent = new Color(specColors.accent ?? '#ff2a38');
  const surface = new Color(specColors.surface ?? '#0b0b10');

  const timelines = [];
  const disposables = [];

  // --- STAGE: engineered gradient backdrop (never void) ---
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  bgMat.colorNode = mix(vec3(surface), vec3(ink), uv().y);
  const bg = new Mesh(bgGeo, bgMat);
  bg.position.set(0, 0, -2.5);
  group.add(bg);
  disposables.push(bgGeo, bgMat);

  // --- MAIN SPRITE: floating accent texture (billboards toward camera by facing +z) ---
  const atlas = config.atlasRegion ?? { x: 0, y: 0, w: 512, h: 320 };
  const aspect = atlas.w / atlas.h; // 1.6
  const planeW = 1.6;
  const planeH = planeW / aspect; // 1.0

  const spriteGeo = new PlaneGeometry(planeW, planeH);
  const spriteMat = new MeshBasicNodeMaterial();
  spriteMat.transparent = true;
  spriteMat.opacity = 1.0;
  const sprite = new Mesh(spriteGeo, spriteMat);
  sprite.position.set(0, 0, 0);
  group.add(sprite);
  disposables.push(spriteGeo, spriteMat);

  // subtle grain modulation node (engineered surface, not flat)
  const grain = Fn(() => {
    const n = fract(sin(uv().x.mul(12.9898).add(uv().y.mul(78.233)).add(time.mul(0.15))).mul(43758.5453));
    return n.sub(0.5).mul(0.015);
  });

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.minFilter = THREE.LinearFilter;
      tex.magFilter = THREE.LinearFilter;
      tex.generateMipmaps = false;
      // atlas UV remap (assumes source rect == full image for atlas index 0)
      const aw = Math.max(atlas.w, 1);
      const ah = Math.max(atlas.h, 1);
      const sx = atlas.x / aw;
      const sy = atlas.y / ah;
      const sw = atlas.w / aw;
      const sh = atlas.h / ah;
      const u = uv();
      const remapU = u.x.mul(sw).add(sx);
      const remapV = u.y.mul(sh).add(sy);
      const texNode = texture(tex, vec3(remapU, remapV, 0).xy);
      // apply subtle grain on top of albedo
      const base = texNode.rgb;
      const grained = base.add(vec3(grain()));
      spriteMat.colorNode = grained;
      spriteMat.alphaNode = texNode.a;
      spriteMat.needsUpdate = true;
    });
  }

  // --- accent hairline under the label (signal red, <=10% of frame) ---
  const lineGeo = new PlaneGeometry(planeW * 0.78, 0.012);
  const lineMat = new MeshBasicNodeMaterial();
  lineMat.colorNode = vec3(accent);
  const line = new Mesh(lineGeo, lineMat);
  line.position.set(0, -planeH * 0.42, 0.001);
  group.add(line);
  disposables.push(lineGeo, lineMat);

  // --- TEXT: "Collection 1" headline via MSDF atlas ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textMeshes = [];
  for (const item of items) {
    const fs = item.typography?.fontSize ?? 39;
    const role = item.role ?? 'headline';
    if (role === 'headline') {
      const t = ctx.fontAtlas.createText(item.text, {
        fontSize: fs,
        color: '#e8ecf2',
        align: 'center',
        letterSpacingPx: 1.2,
      });
      t.position.set(0, -planeH * 0.28, 0.002);
      group.add(t);
      textMeshes.push(t);
    }
  }

  // --- weighted-settle entrance (no primitive; GSAP only) ---
  group.scale.setScalar(0.96);
  group.position.y = 0.04;
  const settleTl = gsap.timeline();
  settleTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
  settleTl.to(group.position, { y: 0, duration: 0.9, ease: 'power3.out' }, 0);
  settleTl.fromTo(bg.material, { opacity: 0 }, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  timelines.push(settleTl);

  // --- cleanup ---
  group.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    for (const t of textMeshes) {
      t.traverse((o) => {
        if (o.geometry && o.geometry.dispose) o.geometry.dispose();
        if (o.material && o.material.dispose) o.material.dispose();
      });
    }
  };

  group.userData.handlers = {};

  return group;
}
